"""Unit tests for .github/scripts/release_gov.py."""

from __future__ import annotations

import json
import os
import pathlib
import stat
import subprocess
import sys
import tempfile
import unittest

SCRIPT_DIR = pathlib.Path(__file__).resolve().parent
if str(SCRIPT_DIR) not in sys.path:
    sys.path.insert(0, str(SCRIPT_DIR))

import release_gov  # noqa: E402


def create_fixture_repo(root: pathlib.Path, version: str = "0.1.0", init_git: bool = False) -> None:
    """Create a minimal valid omk workspace layout inside `root`."""
    (root / "core" / "src").mkdir(parents=True, exist_ok=True)
    (root / "skill" / "src" / "protocol").mkdir(parents=True, exist_ok=True)
    (root / "tests").mkdir(parents=True, exist_ok=True)
    (root / "docs").mkdir(parents=True, exist_ok=True)

    (root / "Cargo.toml").write_text(
        "[workspace]\n"
        'resolver = "2"\n'
        'members = [\n'
        '    "core",\n'
        '    "skill",\n'
        "]\n\n"
        "[workspace.package]\n"
        f'version = "{version}"\n'
        'edition = "2021"\n'
        'license = "MIT"\n',
        encoding="utf-8",
    )

    (root / "core" / "Cargo.toml").write_text(
        "[package]\n"
        'name = "omk-core"\n'
        "version.workspace = true\n"
        "edition.workspace = true\n"
        "license.workspace = true\n",
        encoding="utf-8",
    )

    (root / "skill" / "Cargo.toml").write_text(
        "[package]\n"
        'name = "omk"\n'
        "version.workspace = true\n"
        "edition.workspace = true\n"
        "license.workspace = true\n",
        encoding="utf-8",
    )

    (root / "Cargo.lock").write_text(
        "# This file is automatically @generated by Cargo.\n"
        "version = 4\n\n"
        "[[package]]\n"
        'name = "omk"\n'
        f'version = "{version}"\n'
        "dependencies = [\n"
        ' "omk-core",\n'
        "]\n\n"
        "[[package]]\n"
        'name = "omk-core"\n'
        f'version = "{version}"\n',
        encoding="utf-8",
    )

    (root / "skill" / "src" / "main.rs").write_text(
        'const VERSION: &str = env!("CARGO_PKG_VERSION");\n'
        'fn main() { println!("omk {}", VERSION); }\n',
        encoding="utf-8",
    )

    (root / "skill" / "src" / "protocol" / "mod.rs").write_text(
        'const SERVER_VERSION: &str = env!("CARGO_PKG_VERSION");\n'
        "pub fn version() -> &'static str { SERVER_VERSION }\n",
        encoding="utf-8",
    )

    (root / "tests" / "integration_test.rs").write_text(
        '#[test]\nfn version_matches() { assert_eq!(Some(env!("CARGO_PKG_VERSION")), Some(env!("CARGO_PKG_VERSION"))); }\n',
        encoding="utf-8",
    )

    spec = {
        "jsonrpc": "2.0",
        "protocolVersion": "2024-11-05",
        "name": "omk",
        "version": version,
        "lifecycle": {
            "server/discover": {
                "result": {
                    "serverInfo": {"name": "omk", "version": version},
                }
            },
            "initialize": {
                "result": {
                    "serverInfo": {"name": "omk", "version": version},
                }
            },
        },
    }
    (root / "docs" / "protocol_spec.json").write_text(json.dumps(spec, indent=2) + "\n", encoding="utf-8")

    (root / "CHANGELOG.md").write_text(
        "# Changelog\n\n"
        "All notable changes to `omk` will be documented in this file.\n\n"
        "## [Unreleased]\n",
        encoding="utf-8",
    )

    if init_git:
        subprocess.run(["git", "init", "-b", "main"], cwd=root, check=True, capture_output=True)
        subprocess.run(["git", "config", "user.name", "Test Bot"], cwd=root, check=True, capture_output=True)
        subprocess.run(["git", "config", "user.email", "bot@example.com"], cwd=root, check=True, capture_output=True)
        subprocess.run(["git", "add", "."], cwd=root, check=True, capture_output=True)
        subprocess.run(
            ["git", "commit", "-m", "feat(core): Initial knowledge vault implementation"],
            cwd=root,
            check=True,
            capture_output=True,
        )


class SemVerCalculationTests(unittest.TestCase):
    def test_bootstrap_release_stays_on_initial_version_when_no_tags(self) -> None:
        commits = [
            release_gov.parse_conventional_commit("1111111", "feat(cli): Add omk bench", ""),
            release_gov.parse_conventional_commit("2222222", "fix(skill): Support server/discover", ""),
        ]
        commits = [c for c in commits if c is not None]
        plan = release_gov.compute_next_version(
            current_version="0.1.0",
            latest_tag=None,
            commits=commits,
            release_date="2026-11-22",
        )
        self.assertTrue(plan.should_release)
        self.assertEqual(plan.next_version, "0.1.0")
        self.assertEqual(plan.next_tag, "v0.1.0")
        self.assertEqual(plan.bump_type, "bootstrap")
        self.assertEqual(plan.release_branch, "chore/release-v0.1.0")
        self.assertEqual(plan.pr_title, "chore(release): Prepare v0.1.0")

    def test_feat_bumps_minor_after_tag(self) -> None:
        commits = [
            release_gov.parse_conventional_commit("aaaaaaa", "feat(obs): Add stats subcommand", ""),
            release_gov.parse_conventional_commit("bbbbbbb", "fix(ipc): Prevent socket race", ""),
        ]
        plan = release_gov.compute_next_version(
            current_version="0.1.0",
            latest_tag="v0.1.0",
            commits=[c for c in commits if c is not None],
            release_date="2026-11-22",
        )
        self.assertTrue(plan.should_release)
        self.assertEqual(plan.next_version, "0.2.0")
        self.assertEqual(plan.bump_type, "minor")

    def test_fix_and_perf_bump_patch(self) -> None:
        for header in ("fix(core): Handle empty query", "perf(index): Reuse SQLite reader pool"):
            with self.subTest(header=header):
                entry = release_gov.parse_conventional_commit("ccccccc", header, "")
                assert entry is not None
                plan = release_gov.compute_next_version(
                    current_version="0.1.0",
                    latest_tag="v0.1.0",
                    commits=[entry],
                    release_date="2026-11-22",
                )
                self.assertTrue(plan.should_release)
                self.assertEqual(plan.next_version, "0.1.1")
                self.assertEqual(plan.bump_type, "patch")

    def test_refactor_alone_does_not_bump_but_appears_in_changelog_on_release(self) -> None:
        refactor = release_gov.parse_conventional_commit("ddddddd", "refactor: Simplify proxy framing", "")
        docs = release_gov.parse_conventional_commit("eeeeeee", "docs: Update architecture guide", "")
        assert refactor is not None and docs is not None

        no_release = release_gov.compute_next_version(
            current_version="0.1.0",
            latest_tag="v0.1.0",
            commits=[refactor, docs],
            release_date="2026-11-22",
        )
        self.assertFalse(no_release.should_release)
        self.assertEqual(no_release.bump_type, "none")

        fix = release_gov.parse_conventional_commit("fffffff", "fix(proxy): Retry transient EOF", "")
        assert fix is not None
        with_fix = release_gov.compute_next_version(
            current_version="0.1.0",
            latest_tag="v0.1.0",
            commits=[refactor, fix, docs],
            release_date="2026-11-22",
        )
        self.assertTrue(with_fix.should_release)
        self.assertEqual(with_fix.next_version, "0.1.1")
        self.assertIn("Refactoring", with_fix.sections)
        self.assertIn("Bug Fixes", with_fix.sections)
        self.assertIn("### Refactoring", with_fix.changelog_section)
        self.assertIn("(ddddddd)", with_fix.changelog_section)
        self.assertNotIn("(`ddddddd`)", with_fix.changelog_section)
        self.assertNotIn("Update architecture guide", with_fix.changelog_section)

    def test_zero_x_breaking_change_bumps_minor_not_major(self) -> None:
        bang_commit = release_gov.parse_conventional_commit(
            "1234567",
            "feat(cli)!: Change JSON output schema",
            "",
        )
        footer_commit = release_gov.parse_conventional_commit(
            "7654321",
            "fix(protocol): Enforce strict framing",
            "Details here.\n\nBREAKING CHANGE: Drop legacy framing header.",
        )
        assert bang_commit is not None and footer_commit is not None

        for entry in (bang_commit, footer_commit):
            with self.subTest(desc=entry.description):
                plan = release_gov.compute_next_version(
                    current_version="0.2.3",
                    latest_tag="v0.2.3",
                    commits=[entry],
                    release_date="2026-11-22",
                )
                self.assertTrue(plan.should_release)
                self.assertEqual(plan.next_version, "0.3.0")
                self.assertEqual(plan.bump_type, "minor")
                self.assertIn("### Breaking Changes", plan.changelog_section)

    def test_post_one_zero_breaking_change_bumps_major(self) -> None:
        entry = release_gov.parse_conventional_commit("9999999", "feat!: Remove deprecated RPC", "")
        assert entry is not None
        plan = release_gov.compute_next_version(
            current_version="1.4.2",
            latest_tag="v1.4.2",
            commits=[entry],
            release_date="2026-11-22",
        )
        self.assertTrue(plan.should_release)
        self.assertEqual(plan.next_version, "2.0.0")
        self.assertEqual(plan.bump_type, "major")

    def test_release_as_explicit_promotion_to_1_0_0_and_downgrade_rejection(self) -> None:
        plan = release_gov.compute_next_version(
            current_version="0.4.1",
            latest_tag="v0.4.1",
            commits=[],
            release_as="1.0.0",
            release_date="2026-11-22",
        )
        self.assertTrue(plan.should_release)
        self.assertEqual(plan.next_version, "1.0.0")
        self.assertEqual(plan.bump_type, "manual")
        self.assertIn("### Maintenance", plan.changelog_section)

        with self.assertRaises(ValueError):
            release_gov.compute_next_version(
                current_version="0.4.1",
                latest_tag="v0.4.1",
                commits=[],
                release_as="0.4.1",
            )

    def test_detect_release_commit_subject(self) -> None:
        self.assertEqual(
            release_gov.detect_release_commit_subject("chore(release): Prepare v0.1.0"),
            "0.1.0",
        )
        self.assertEqual(
            release_gov.detect_release_commit_subject("chore(release): Prepare v1.2.3 (#42)"),
            "1.2.3",
        )
        self.assertIsNone(release_gov.detect_release_commit_subject("feat(cli): Add version flag (#5)"))
        self.assertIsNone(release_gov.detect_release_commit_subject("chore(release): Prepare v01.2.3"))


class SsotAndHardcodingTests(unittest.TestCase):
    def test_valid_fixture_passes_ssot(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            root = pathlib.Path(tmp)
            create_fixture_repo(root, version="0.1.0")
            self.assertEqual(release_gov.check_ssot(root), [])

    def test_member_manifest_hardcoded_version_fails(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            root = pathlib.Path(tmp)
            create_fixture_repo(root, version="0.1.0")
            (root / "core" / "Cargo.toml").write_text(
                '[package]\nname = "omk-core"\nversion = "0.1.0"\nedition.workspace = true\nlicense.workspace = true\n',
                encoding="utf-8",
            )
            errors = release_gov.check_ssot(root)
            self.assertTrue(any("core/Cargo.toml" in e and "version" in e for e in errors), errors)

    def test_rust_source_and_test_hardcoding_detected_while_comments_ignored(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            root = pathlib.Path(tmp)
            create_fixture_repo(root, version="0.1.0")

            # Comments mentioning "0.1.0" must not cause false positives.
            (root / "core" / "src" / "lib.rs").write_text(
                '// Introduced in "0.1.0"\n/* legacy "0.1.0" comment */\npub fn ok() -> bool { true }\n',
                encoding="utf-8",
            )
            self.assertEqual(release_gov.check_ssot(root), [])

            # Hardcoded version in integration test must fail.
            (root / "tests" / "integration_test.rs").write_text(
                '#[test]\nfn bad() { assert_eq!(Some("0.1.0"), Some("0.1.0")); }\n',
                encoding="utf-8",
            )
            errors = release_gov.check_ssot(root)
            self.assertTrue(any("integration_test.rs" in e for e in errors), errors)

    def test_protocol_spec_mismatch_detected(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            root = pathlib.Path(tmp)
            create_fixture_repo(root, version="0.1.0")
            spec_path = root / "docs" / "protocol_spec.json"
            spec = json.loads(spec_path.read_text(encoding="utf-8"))
            spec["lifecycle"]["initialize"]["result"]["serverInfo"]["version"] = "0.0.9"
            spec_path.write_text(json.dumps(spec, indent=2), encoding="utf-8")

            errors = release_gov.check_ssot(root)
            self.assertTrue(any("initialize" in e for e in errors), errors)


class BumpChangelogAndIntegrityTests(unittest.TestCase):
    def test_bump_updates_all_files_and_is_idempotent(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            root = pathlib.Path(tmp)
            create_fixture_repo(root, version="0.1.0", init_git=True)

            rc = release_gov.main(
                [
                    "bump",
                    "--repo-root",
                    str(root),
                    "--version",
                    "0.2.0",
                    "--date",
                    "2026-11-22",
                    "--skip-cargo-lock-check",
                ]
            )
            self.assertEqual(rc, 0)
            self.assertEqual(release_gov.check_ssot(root), [])
            self.assertEqual(release_gov.read_workspace_version(root), "0.2.0")

            changelog = (root / "CHANGELOG.md").read_text(encoding="utf-8")
            self.assertIn("## [v0.2.0] - 2026-11-22", changelog)
            self.assertIn("Initial knowledge vault implementation", changelog)

            # Re-running bump for the same version replaces section without duplicating it.
            rc_again = release_gov.main(
                [
                    "bump",
                    "--repo-root",
                    str(root),
                    "--version",
                    "0.2.0",
                    "--date",
                    "2026-11-23",
                    "--skip-cargo-lock-check",
                ]
            )
            self.assertEqual(rc_again, 0)
            changelog_again = (root / "CHANGELOG.md").read_text(encoding="utf-8")
            self.assertEqual(changelog_again.count("## [v0.2.0]"), 1)
            self.assertIn("## [v0.2.0] - 2026-11-23", changelog_again)

            # extract-notes returns the exact section body.
            notes = release_gov.extract_release_notes(changelog_again, "v0.2.0")
            self.assertIn("### Features", notes)
            self.assertIn("Initial knowledge vault implementation", notes)

            with self.assertRaises(ValueError):
                release_gov.extract_release_notes(changelog_again, "v9.9.9")

    def test_five_way_version_integrity_gate(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            root = pathlib.Path(tmp)
            create_fixture_repo(root, version="0.2.0")

            good_bin = root / "mock-omk-good"
            good_bin.write_text("#!/bin/sh\necho 'omk 0.2.0'\n", encoding="utf-8")
            good_bin.chmod(good_bin.stat().st_mode | stat.S_IXUSR)

            bad_bin = root / "mock-omk-bad"
            bad_bin.write_text("#!/bin/sh\necho 'omk 0.1.0'\n", encoding="utf-8")
            bad_bin.chmod(bad_bin.stat().st_mode | stat.S_IXUSR)

            # 1. All 5 sources match -> pass
            self.assertEqual(release_gov.verify_release(root, "v0.2.0", binary=good_bin), [])

            # 2. Tag mismatch -> fail
            tag_errors = release_gov.verify_release(root, "v0.3.0", binary=good_bin)
            self.assertTrue(any("Tag/Cargo.toml" in e for e in tag_errors), tag_errors)

            # 3. Runtime binary mismatch -> fail
            bin_errors = release_gov.verify_release(root, "v0.2.0", binary=bad_bin)
            self.assertTrue(any("Binary --version output mismatch" in e for e in bin_errors), bin_errors)

            # 4. Cargo.lock mismatch -> fail
            (root / "Cargo.lock").write_text(
                'version = 4\n[[package]]\nname = "omk"\nversion = "0.1.0"\n'
                '[[package]]\nname = "omk-core"\nversion = "0.2.0"\n',
                encoding="utf-8",
            )
            lock_errors = release_gov.verify_release(root, "v0.2.0", binary=good_bin)
            self.assertTrue(any("Cargo.lock" in e for e in lock_errors), lock_errors)

            # 5. Invalid tag format -> fail
            fmt_errors = release_gov.verify_release(root, "0.2.0")
            self.assertTrue(any("Invalid release tag" in e for e in fmt_errors), fmt_errors)


if __name__ == "__main__":
    unittest.main()
